import Vue from 'vue';
import VueRouter from 'vue-router';
import RecruitmentPage from '../views/RecruitmentPage.vue';
import RecruitmentInfoPage from '../views/RecruitmentInfoPage.vue';
import HomePage from '../views/HomePage.vue';
Vue.use(VueRouter);
const routes = [{
  path: '/',
  redirect: '/home'
}, {
  path: '/home',
  name: 'Home',
  component: HomePage
}, {
  path: '/admission',
  name: 'Admission',
  component: RecruitmentPage,
  props: {
    activeTab: 'admission'
  }
}, {
  path: '/recruitment',
  name: 'Recruitment',
  component: RecruitmentPage,
  props: {
    activeTab: 'recruitment'
  }
}, {
  path: '/recruitment-info',
  name: 'RecruitmentInfo',
  component: RecruitmentInfoPage
}, {
  path: '/registration',
  name: 'Registration',
  component: RecruitmentPage,
  props: {
    activeTab: 'registration'
  }
}, {
  path: '/contact',
  name: 'Contact',
  component: RecruitmentPage,
  props: {
    activeTab: 'contact'
  }
}];
const router = new VueRouter({
  mode: 'history',
  base: process.env.BASE_URL,
  routes
});
export default router;
